/**
 * Import products from scraped Excel data (pre-processed JSON)
 *
 * Usage: node import-products.mjs
 *
 * Reads import-data.json (generated by Python script) and inserts
 * products + variants into the database, mapping to existing categories.
 */

import postgres from 'postgres'
import { readFileSync } from 'fs'
import { randomUUID } from 'crypto'

const DATABASE_URL = process.env.DATABASE_URL || 'postgres://appuser:k21devpass@localhost:5433/k21'
const sql = postgres(DATABASE_URL)

async function main() {
  try {
    // 1. Load import data
    const data = JSON.parse(readFileSync(new URL('./import-data.json', import.meta.url), 'utf-8'))
    console.log(`📦 Loaded ${data.length} products to import`)

    // 2. Fetch existing categories
    const categories = await sql`SELECT id, name FROM categories`
    const catMap = Object.fromEntries(categories.map(c => [c.name, c.id]))
    console.log(`📂 Found ${categories.length} categories:`, Object.keys(catMap).join(', '))

    // 3. Get a system user (first admin/owner) for created_by
    const [adminUser] = await sql`
      SELECT id FROM users WHERE role IN ('Owner', 'Admin') LIMIT 1
    `
    if (!adminUser) {
      console.error('❌ No admin/owner user found. Need a user for created_by field.')
      process.exit(1)
    }
    const createdBy = adminUser.id
    console.log(`👤 Using user ${createdBy} as created_by`)

    // 4. Check for existing products to avoid duplicates
    const existing = await sql`SELECT name FROM products`
    const existingNames = new Set(existing.map(p => p.name))

    let insertedProducts = 0
    let insertedVariants = 0
    let skippedProducts = 0

    // 5. Insert products and variants
    for (const product of data) {
      // Skip if already exists
      if (existingNames.has(product.name)) {
        skippedProducts++
        continue
      }

      const categoryId = catMap[product.category]
      if (!categoryId) {
        console.warn(`⚠️  Category "${product.category}" not found, skipping: ${product.name}`)
        continue
      }

      // Insert product
      const [inserted] = await sql`
        INSERT INTO products (name, category_id, ppn_type, is_active, created_by)
        VALUES (${product.name}, ${categoryId}, 'TAXABLE', true, ${createdBy})
        RETURNING id
      `

      insertedProducts++

      // Insert variants
      for (const variant of product.variants) {
        await sql`
          INSERT INTO product_variants (product_id, sku, attributes, price, cost_price, stock_qty)
          VALUES (
            ${inserted.id},
            ${variant.sku},
            ${JSON.stringify(variant.attributes)}::jsonb,
            ${variant.price},
            ${variant.cost_price},
            0
          )
        `
        insertedVariants++
      }
    }

    console.log('')
    console.log('✅ Import complete!')
    console.log(`   Products inserted: ${insertedProducts}`)
    console.log(`   Variants inserted: ${insertedVariants}`)
    console.log(`   Products skipped (already exist): ${skippedProducts}`)

    // 6. Summary by category
    const summary = await sql`
      SELECT c.name as category, COUNT(p.id) as count
      FROM products p
      JOIN categories c ON p.category_id = c.id
      GROUP BY c.name
      ORDER BY count DESC
    `
    console.log('\n📊 Products per category:')
    for (const row of summary) {
      console.log(`   ${row.category}: ${row.count}`)
    }

  } catch (err) {
    console.error('❌ Error:', err.message)
    if (err.message.includes('unique')) {
      console.log('💡 Some SKUs may already exist. Try running with fresh data or clear existing products first.')
    }
    throw err
  } finally {
    await sql.end()
  }
}

main()
